@Component("forecast-handler")
@ProcessingGroup("forecast-processing-group")
public class ForecastEventHandler {
	
	// core constructor
	ForecastEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateForecastEvent
     */
    @EventHandler
    public void handle( CreateForecastEvent event) {
        entityManager.persist(new Forecast(event.getForecastId(), event.getName(), event.getHorizon(), event.getModelVersion(), event.getTimeSeries(), event.getDatasets(), event.getGranularity()));
    }

    /*
     * @param	event UpdateForecastEvent
     */
    @EventHandler
    public Forecast handle( UpdateForecastEvent event) {
    	entityManager.merge(new Forecast(event.getForecastId(), event.getName(), event.getHorizon(), event.getModelVersion(), event.getTimeSeries(), event.getDatasets(), event.getGranularity()));
    }
    
    /*
     * @param	event DeleteForecastEvent
     */
    @EventHandler
    public void on( DeleteForecastEvent event) {
    	Forecast entity = new Forecast();
   
    	// ------------------------------------------
    	// apply the ForecastId
    	// ------------------------------------------
    	entity.setForecastId( event.getForecastId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ForecastRepository forecastEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ForecastEventHandler.class.getName());

}
